mapper.select:
WITH totalInventory as ( select warehouse_id,sku_id,warehouse_location, case when dict_inventory_status in ('usable','frozen') then sum(qty) else 0 end as realQty, case when dict_inventory_status = 'usable' then sum(qty) else 0 end as useQty, case when dict_inventory_status = 'frozen' then sum(qty) else 0 end as freezeQty, case when dict_inventory_status = 'inTransit' then sum(qty) else 0 end as inTransitQty from inventory where is_deleted = false group by warehouse_id,sku_id,warehouse_location,dict_inventory_status ) select pd.images_url as imagesUrl, pd.id as skuId, pd.sku_no as skuNo, pd.name as productName, ps.sale_state as saleState, wh.name as warehouseName, inv.realQty, inv.useQty, inv.freezeQty, inv.inTransitQty from totalInventory inv left join product_detail pd on inv.sku_id = pd.id and pd.is_deleted = false left join product_sale ps on inv.sku_id = ps.sku_id and ps.is_deleted = false left join warehouse wh on inv.warehouse_id = wh.id and wh.is_deleted = false left join warehouse_location wl on wh.id = wl.warehouse_id and inv.warehouse_location = wl.code and wl.is_deleted = false WHERE ${params.sqlMap.default} ORDER BY
${item.field} ${item.sort}
inv.warehouse_id,inv.sku_id
